const data = $input.first().json;
const repoUrl = $('Webhook Trigger').first().json.body.url;

// Cor do embed baseada na nota
let color = 15548997; // vermelho
if (data.score >= 8) color = 5763719;  // verde
else if (data.score >= 5) color = 16776960; // amarelo

// Extrair seções do relatório Markdown
let escopo = '';
let pontosFortes = '';
let problemas = '';
let checklist = '';
let nota = '';
let limitacoes = '';

if (data.report) {
  // Escopo
  const escopoMatch = data.report.match(/## Escopo\n([\s\S]*?)(?=\n## )/);
  if (escopoMatch) {
    escopo = escopoMatch[1].trim().substring(0, 1024);
  }

  // Pontos Fortes
  const forteMatch = data.report.match(/## Pontos Fortes\n([\s\S]*?)(?=\n## )/);
  if (forteMatch) {
    pontosFortes = forteMatch[1].trim().substring(0, 1024);
  }

  // Problemas Identificados
  const probMatch = data.report.match(/## Problemas Identificados\n([\s\S]*?)(?=\n## )/);
  if (probMatch) {
    problemas = probMatch[1].trim().substring(0, 1024);
  }

  // Checklist de Melhorias
  const checkMatch = data.report.match(/## Checklist de Melhorias\n([\s\S]*?)(?=\n## )/);
  if (checkMatch) {
    checklist = checkMatch[1].trim().substring(0, 1024);
  }

  // Nota (inclui justificativa)
  const notaMatch = data.report.match(/## Nota\n([\s\S]*?)(?=\n## )/);
  if (notaMatch) {
    nota = notaMatch[1].trim().substring(0, 1024);
  }

  // Limitações (última seção, pode não ter ## depois)
  const limMatch = data.report.match(/## Limitações\n([\s\S]*?)$/);
  if (limMatch) {
    limitacoes = limMatch[1].trim().substring(0, 1024);
  }
}

// Montar dimensões como tabela formatada
let dimensionsText = '';
if (data.dimensions && typeof data.dimensions === 'object') {
  dimensionsText = Object.entries(data.dimensions)
    .map(([k, v]) => `**${k.charAt(0).toUpperCase() + k.slice(1)}:** ${v}`)
    .join('\n');
}

// Montar embeds (Discord aceita até 10 embeds por mensagem)
const embeds = [];

// Embed 1: Resumo + Escopo
embeds.push({
  title: '📄 Relatório de Análise de Documentação',
  url: repoUrl,
  color: color,
  description: `Análise completa da documentação do projeto.\n\n📁 **Repositório:** ${repoUrl}`,
  fields: [
    { name: '📂 Escopo', value: escopo || 'N/A', inline: false }
  ]
});

// Embed 2: Pontos Fortes
if (pontosFortes) {
  embeds.push({
    title: '✅ Pontos Fortes',
    color: 5763719,
    description: pontosFortes
  });
}

// Embed 3: Problemas Identificados
if (problemas) {
  embeds.push({
    title: '⚠️ Problemas Identificados',
    color: 16776960,
    description: problemas
  });
}

// Embed 4: Checklist de Melhorias
if (checklist) {
  embeds.push({
    title: '📝 Checklist de Melhorias',
    color: 3447003,
    description: checklist
  });
}

// Embed 5: Nota + Dimensões
const notaFields = [
  { name: '⭐ Nota', value: `**${data.score}/10**`, inline: true },
  { name: '📋 Pontos Fortes', value: String(data.strengths_count), inline: true },
  { name: '⚠️ Problemas', value: String(data.issues_count), inline: true }
];
if (dimensionsText) {
  notaFields.push({ name: '📊 Dimensões', value: dimensionsText, inline: false });
}
const notaEmbed = {
  title: '🏆 Nota',
  color: color,
  fields: notaFields
};
if (nota) {
  // Pegar apenas a justificativa (remover a nota numérica que já está nos fields)
  const justificativa = nota.replace(/\*\*\d+\/10\*\*\n?/, '').trim();
  if (justificativa) {
    notaEmbed.description = justificativa.substring(0, 2048);
  }
}
embeds.push(notaEmbed);

// Embed 6: Limitações
if (limitacoes) {
  embeds.push({
    title: '⚙️ Limitações',
    color: 9807270,
    description: limitacoes
  });
}

// Footer no último embed
embeds[embeds.length - 1].footer = {
  text: `Doc Intelligence Agent | Trace: ${data.trace_id}`
};
embeds[embeds.length - 1].timestamp = new Date().toISOString();

return [{ json: { embeds } }];
